<script setup lang="ts">
import TableToolbar from './TableToolbar.vue'
import {ref,onMounted,computed,watch} from 'vue'
import {api,allows,createRequest,type Workspace} from './api'
import {say as s} from './iam'
import {message} from './i18n'
import MenuRows from './PublicationMenuRows.vue'
const props=defineProps<{space:{id:number;site_id:number;code:string;name:string};workspace:Workspace}>()
const base='/publication/spaces/'+props.space.id
const can=(p:string)=>allows(props.workspace,p,props.space.site_id)
const post=createRequest()
type Block={type:string;text?:string;media_id?:string;alt?:string;items?:string[]}
const blank=()=>({title:'',summary:'',cover_media_id:'',body_blocks:[] as Block[],seo_meta:{title:'',description:'',robots:'index,follow',og_image_media:''}})
type Entry={id:string;entry_type:string;locale:string;status:string;revision:number;working_data:ReturnType<typeof blank>;working_slug:string;published_slug:string;working_in_review:boolean;has_unpublished_changes:boolean;translation_group_id:string}
type Media={id:string;name:string;revision:number;visibility:string;mime:string;staff_uploaded:boolean}
type Comment={id:string;revision:number;author:string;status:string;body_text:string;reason:string}
const tab=ref('entries'),rows=ref<Entry[]>([]),assets=ref<Media[]>([]),subs=ref<Comment[]>([]),editing=ref(false),id=ref(''),version=ref(0),kind=ref('page'),lang=ref('en'),peer=ref(''),slug=ref(''),draft=ref(blank()),block=ref('paragraph'),asset=ref(''),notice=ref(''),error=ref(''),busy=ref(false)
const publicImages=computed(()=>assets.value.filter(a=>a.visibility==='public'&&a.staff_uploaded))
const locale=ref('en'),location=ref('header'),menu=ref<{revision:number;items:any[]}>({revision:0,items:[]}),filter=ref('pending'),reason=ref('')
const actions:Record<string,[string,string]>={'submit-review':['Submit for review','إرسال للمراجعة'],publish:['Publish','نشر'],unpublish:['Unpublish','سحب النشر'],archive:['Archive','أرشفة'],approve:['Approve','اعتماد'],reject:['Reject','رفض'],hide:['Hide','إخفاء']}
const words:Record<string,string>={draft:'مسودة',published:'منشور',in_review:'قيد المراجعة',archived:'مؤرشف',pending:'معلق',approved:'معتمد',rejected:'مرفوض',hidden:'مخفي',heading:'عنوان',paragraph:'فقرة',list:'قائمة',quote:'اقتباس',image:'صورة',callout:'تنويه',code:'كود'}
const types=['heading','paragraph','list','quote','image','callout','code']
const word=(v:string)=>s(v,words[v]||v)
async function run(fn:()=>Promise<void>,saved=false){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();if(saved)notice.value=s('Saved','تم الحفظ')}catch(e){error.value=message(e)}finally{busy.value=false}}
const choices=ref<Pick<Entry,'id'|'entry_type'|'locale'|'working_data'|'translation_group_id'>[]>([]),pg=ref(1),size=ref(25),term=ref(''),count=ref(0)
let serial=0
const query=()=>new URLSearchParams({page:String(pg.value),page_size:String(size.value),q:term.value,status:filter.value})
async function load(){const key=++serial;const d=await api<{results:Entry[];count:number;choices:typeof choices.value}>(base+'/entries?'+query());if(key===serial){rows.value=d.results;count.value=d.count;choices.value=d.choices}}
async function media(){if(!can('media_service.view'))return;let page=1;const found:Media[]=[];while(true){const r=await api<{results:Media[];next:string|null}>('/platform/v1/media?space_id='+props.space.id+'&page='+page++);found.push(...r.results.filter(a=>a.mime.startsWith('image/')));if(!r.next)break}assets.value=found}
function edit(r?:Entry){editing.value=true;id.value=r?.id||'';version.value=r?.revision||0;slug.value=r?.working_slug||'';kind.value=r?.entry_type||'page';lang.value=r?.locale||'en';peer.value='';draft.value=r?JSON.parse(JSON.stringify(r.working_data)):blank()}
function translation(){const r=choices.value.find(x=>x.id===peer.value);if(r){kind.value=r.entry_type;lang.value=r.locale==='en'?'ar':'en'}}
async function save(){await api(base+'/entries'+(id.value?'/'+id.value:''),id.value?'PATCH':'POST',{revision:version.value,locale:lang.value,entry_type:kind.value,working_slug:slug.value,working_data:draft.value,translation_of:peer.value});await load();editing.value=false}
async function move(r:Entry,a:string){await post(base+'/entries/'+r.id+'/'+a,{revision:r.revision});await load()}
const menuPath=()=>base+'/menus/'+locale.value+'/'+location.value
async function getMenu(){menu.value=await api(menuPath())}
async function moderate(){const key=++serial;const d=await api<{results:Comment[];count:number}>(base+'/submissions?'+query());if(key===serial){subs.value=d.results;count.value=d.count}}
watch([pg,size,term,filter],()=>{void (tab.value==='comments'?moderate():load()).catch(e=>error.value=message(e))})
async function switchTab(t:string){tab.value=t;editing.value=false;pg.value=1;term.value='';if(t==='entries')await load();if(t==='menus')await getMenu();if(t==='comments')await moderate()}
onMounted(()=>run(async()=>{await load();await media()}))
</script>
<template><section class="panel stack"><h2>{{space.name}}</h2><nav class="actions"><button v-for="[key,en,ar] in [['entries','Pages & posts','الصفحات والمقالات'],['menus','Navigation menus','قوائم التنقل'],['comments','Moderation','مراجعة التعليقات']]" v-show="key!=='comments'||can('publication.moderate')" :class="{primary:tab===key}" :disabled="busy" @click="run(()=>switchTab(key))">{{s(en,ar)}}</button></nav>
<p v-if="error" role="alert" class="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<TableToolbar v-if="tab!=='menus'&&!editing" :page="pg" :size="size" :count="count" :query="term" @page="pg=$event" @size="pg=1;size=$event" @search="pg=1;term=$event"/>
<template v-if="tab==='entries' && !editing"><button v-if="can('publication.manage')" :disabled="busy" @click="edit()">{{s('New entry','محتوى جديد')}}</button>
<article class="panel" v-for="r in rows" :key="r.id"><strong>{{r.working_data.title}}</strong> · {{r.locale.toUpperCase()}} · {{word(r.status)}} <span v-if="r.has_unpublished_changes">· {{s('Unpublished edits','تعديلات غير منشورة')}}</span> <span v-if="r.working_in_review">· {{word('in_review')}}</span>
<p>{{s('Translations','الترجمات')}} · {{choices.filter(x=>x.translation_group_id===r.translation_group_id).map(x=>x.locale.toUpperCase()).join(' / ')}} <a v-if="r.status==='published'" :href="'/public/site/'+space.code+'/'+r.entry_type+'s/'+encodeURIComponent(r.published_slug)+'?lang='+r.locale" target="_blank" rel="noopener">{{s('Open published page','فتح الصفحة المنشورة')}}</a></p>
<div class="actions" v-if="r.status!=='archived'"><button v-if="can('publication.manage')" @click="edit(r)">{{s('Edit','تعديل')}}</button><button v-for="a in ['submit-review','publish','unpublish','archive']" v-show="can(a==='submit-review'?'publication.manage':'publication.publish') && (a!=='unpublish'||r.status==='published') && (a!=='submit-review'||r.has_unpublished_changes&&!r.working_in_review)" :disabled="busy" @click="run(()=>move(r,a),true)">{{s(...actions[a])}}</button></div></article></template>
<form v-else-if="tab==='entries'" class="record-form" @submit.prevent="run(save,true)">
<label v-if="!id">{{s('Translation of','ترجمة للمحتوى')}}<select v-model="peer" @change="translation"><option value="">—</option><option v-for="r in choices" :value="r.id">{{r.working_data.title}} ({{r.locale}})</option></select></label>
<label>{{s('Type','النوع')}}<select v-model="kind" :disabled="!!id||!!peer"><option value="page">{{s('Page','صفحة')}}</option><option value="post">{{s('Post','مقال')}}</option></select></label>
<label>{{s('Content language','لغة المحتوى')}}<select v-model="lang" :disabled="!!id||!!peer"><option value="en">English</option><option value="ar">العربية</option></select></label>
<label>{{s('Title','العنوان')}}<input v-model="draft.title" maxlength="200" required></label><label>{{s('URL slug','اسم الرابط')}}<input v-model="slug" required></label><label>{{s('Summary','الملخص')}}<textarea v-model="draft.summary"/></label>
<fieldset><legend>{{s('Content blocks','عناصر المحتوى')}}</legend><div class="stack" v-for="(b,i) in draft.body_blocks" :key="i"><label>{{word(b.type)}}<template v-if="b.type==='image'"><select v-model="b.media_id" required><option v-for="m in publicImages" :value="m.id">{{m.name}}</option></select><input v-model="b.alt" :placeholder="s('Alternative text','وصف الصورة')"></template><textarea v-else-if="b.type==='list'" :value="b.items?.join('\n')" @input="b.items=($event.target as HTMLTextAreaElement).value.split('\n')"/><textarea v-else v-model="b.text" required/></label><button type="button" @click="draft.body_blocks.splice(i,1)">{{s('Remove','حذف')}}</button></div><select v-model="block"><option v-for="b in types" :value="b">{{word(b)}}</option></select><button type="button" @click="draft.body_blocks.push({type:block})">{{s('Add block','إضافة عنصر')}}</button></fieldset>
<label>{{s('Cover image','صورة الغلاف')}}<select v-model="draft.cover_media_id"><option value="">—</option><option v-for="m in publicImages" :value="m.id">{{m.name}}</option></select></label>
<fieldset v-if="can('media_service.manage')"><legend>{{s('Private staff images','صور الموظفين الخاصة')}}</legend><select v-model="asset"><option value="">—</option><option v-for="m in assets.filter(a=>a.staff_uploaded&&a.visibility==='private')" :value="m.id">{{m.name}}</option></select><button :disabled="!asset||busy" type="button" @click="run(async()=>{await post('/media-service/assets/'+asset+'/promote-public',{revision:assets.find(a=>a.id===asset)?.revision});await media();asset=''},true)">{{s('Promote to Public Image','إتاحة الصورة للعامة')}}</button></fieldset>
<label>{{s('SEO title','عنوان محركات البحث')}} ({{draft.seo_meta.title.length}}/200)<input v-model="draft.seo_meta.title" maxlength="200"></label><label>{{s('Meta description','وصف محركات البحث')}} ({{draft.seo_meta.description.length}}/500)<textarea v-model="draft.seo_meta.description" maxlength="500"/></label>
<label>{{s('Indexing','الفهرسة')}}<select v-model="draft.seo_meta.robots"><option>index,follow</option><option>noindex,follow</option><option>noindex,nofollow</option></select></label><label>{{s('Social preview image','صورة المشاركة')}}<select v-model="draft.seo_meta.og_image_media"><option value="">—</option><option v-for="m in publicImages" :value="m.id">{{m.name}}</option></select></label><div class="actions"><button class="primary" :disabled="busy">{{s('Save draft','حفظ المسودة')}}</button><button type="button" @click="editing=false">{{s('Cancel','إلغاء')}}</button></div></form>
<template v-else-if="tab==='menus'"><div class="actions"><select v-model="locale" :disabled="busy" @change="run(getMenu)"><option>en</option><option>ar</option></select><select v-model="location" :disabled="busy" @change="run(getMenu)"><option value="header">{{s('Header','الترويسة')}}</option><option value="footer">{{s('Footer','التذييل')}}</option></select></div><fieldset :disabled="!can('publication.manage')||busy"><MenuRows :items="menu.items" :entries="choices.filter(r=>r.locale===locale)" :depth="1"/><button @click="run(async()=>{menu=await api(menuPath(),'PUT',menu)},true)">{{s('Save menu','حفظ القائمة')}}</button></fieldset></template>
<template v-else><select v-model="filter"><option v-for="v in ['pending','approved','rejected','hidden']" :value="v">{{word(v)}}</option></select><label>{{s('Moderation reason','سبب القرار')}}<input v-model="reason" maxlength="500"></label><article v-for="r in subs.filter(x=>x.status===filter)" class="panel"><strong>{{r.author}}</strong><p>{{r.body_text}}</p><p>{{r.reason}}</p><button v-for="a in ['approve','reject','hide']" :disabled="busy" v-show="(a!=='hide'||r.status==='approved')&&r.status!==({approve:'approved',reject:'rejected'} as Record<string,string>)[a]" @click="run(async()=>{await post(base+'/submissions/'+r.id+'/'+a,{revision:r.revision,reason});reason='';await moderate()},true)">{{s(...actions[a])}}</button></article></template></section></template>
